const chip=(text,type='')=>`<span class="chip ${type}">${text}</span>`;
const pageLead=(title,desc,extra='')=>`<div class="page-lead"><div><h2>${title}</h2><p>${desc}</p></div>${extra}</div>`;
const periodTabs=(compact=false)=>`<div class="period-tabs ${compact?'compact':''}">${periodOptions.map(([k,v])=>`<button class="period-btn ${state.range===k?'active':''}" data-action="${k==='custom'?'custom-date':'range'}" data-range="${k}">${v}</button>`).join('')}</div>`;
const periodBadge=()=>{const [label,date='']=periodText[state.range].split(' · ');return `<span class="period-label">${label}</span>${date?`<span class="period-date">${date}</span>`:''}`};
function table(headers,rows,cls=''){return `<div class="table-wrap"><table class="data-table ${cls}"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function kpi(title,value,foot,icon,target,kind=''){return `<article class="kpi ${target?'clickable':''} ${kind}" ${target?`data-action="goto" data-view="${target}"`:''}><div class="kpi-top">${title}<span class="kpi-icon">${icon}</span></div><div class="kpi-value">${value}</div><div class="kpi-foot">${foot}</div>${target?'<span class="kpi-link">查看明细 →</span>':''}</article>`}
function activeDataFactor(){const group={全部:1,A组:.34,B组:.37,C组:.29}[state.dataGroup]||1;const platform=state.dataPlatform==='全部'?1:.48;const biz=state.dataBiz==='全部'?1:.42;return group*platform*biz}
function chart(compact=false){const factor=state.view==='data'?activeDataFactor():1;const data=chartSets[state.range].map(x=>[x[0],Math.max(1,Math.round(x[1]*factor)),Math.round(x[2]*factor)]),maxO=Math.max(...data.map(x=>x[1]))*1.15,maxC=Math.max(...data.map(x=>x[2]))*1.15,w=720,h=compact?172:220,pL=43,pR=48,pT=18,pB=32,iw=w-pL-pR,ih=h-pT-pB,step=iw/data.length,labelEvery=data.length>24?5:data.length>14?3:1;const grid=[0,.25,.5,.75,1].map(v=>`<line x1="${pL}" y1="${pT+ih*v}" x2="${w-pR}" y2="${pT+ih*v}" stroke="#edf0f4"/><text x="${pL-8}" y="${pT+ih*v+4}" text-anchor="end" fill="#99a3b2" font-size="9">${Math.round(maxO*(1-v))}</text><text x="${w-pR+7}" y="${pT+ih*v+4}" fill="#99a3b2" font-size="9">¥${Math.round(maxC*(1-v)/100)/10}k</text>`).join('');const bars=data.map((x,i)=>{const bh=x[1]/maxO*ih,label=i%labelEvery===0||i===data.length-1;return `<rect x="${pL+i*step+step*.22}" y="${pT+ih-bh}" width="${Math.max(3,step*.56)}" height="${bh}" rx="${data.length>16?2:4}" fill="#3f6ef2"><title>${x[0]}：${x[1]} 单，佣金 ¥${x[2]}</title></rect>${data.length<=10?`<text x="${pL+i*step+step*.5}" y="${pT+ih-bh-5}" text-anchor="middle" fill="#536078" font-size="9">${x[1]}</text>`:''}${label?`<text x="${pL+i*step+step*.5}" y="${h-9}" text-anchor="middle" fill="#8793a5" font-size="9">${x[0]}</text>`:''}`}).join('');const pts=data.map((x,i)=>`${pL+i*step+step*.5},${pT+ih-x[2]/maxC*ih}`).join(' ');const dots=data.length<=10?data.map((x,i)=>`<circle cx="${pL+i*step+step*.5}" cy="${pT+ih-x[2]/maxC*ih}" r="3.7" fill="#f3ca65" stroke="#fff" stroke-width="2"/>`).join(''):'';return `<div class="chart-wrap ${compact?'compact-chart':''}"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${periodText[state.range]}有效订单与佣金趋势">${grid}${bars}<polyline points="${pts}" fill="none" stroke="#e3ad31" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${dots}</svg></div><div class="chart-legend"><span><i class="legend-bar"></i>有效订单</span><span><i class="legend-line"></i>预估佣金</span><strong>${periodText[state.range]}</strong></div>`}

function overview(){const s=summary[state.range],urgent=incentiveActivities.filter(a=>a.phase==='upcoming'||a.status.includes('结束'));const activityPanel=`<div class="card priority-card"><div class="card-head"><div><h3>激励活动提醒</h3><p>${urgent.length?'有新活动或临期活动，已自动前置':'暂无临期活动'}</p></div><a data-action="goto" data-view="business">全部活动 →</a></div>${urgent.slice(0,2).map((a,i)=>`<div class="task-mini activity-priority" data-action="activity-detail" data-id="${a.id}"><i class="mini-dot ${i?'':'yellow'}"></i><div><strong>${a.name} · ${a.status}</strong><span>${a.start}—${a.end} · ${a.bonus}</span></div></div>`).join('')}</div>`;const taskPanel=`<div class="card"><div class="card-head"><div><h3>今天需要处理</h3><p>临期和逾期任务</p></div><a data-action="goto" data-view="tasks">全部任务 →</a></div><div class="task-mini"><i class="mini-dot"></i><div><strong>CPS 周报核对</strong><span>胡心玥 · 已逾期 1 天 · 进行中</span></div></div><div class="task-mini"><i class="mini-dot yellow"></i><div><strong>品牌观察站违规申诉</strong><span>胡心玥 · 今天 18:00 截止</span></div></div></div>`;const side=urgent.length?activityPanel+taskPanel:taskPanel+activityPanel;return `${pageLead('今日先看重点','收益、账号异常、激励活动和长期任务集中在同一屏',periodTabs())}<div class="notice period-notice"><span>${periodBadge()}<span class="notice-copy">时间切换会同步更新指标和下方趋势图</span></span><a data-action="goto" data-view="data">进入数据中心</a></div><div class="kpi-grid">${kpi('预估佣金',s[0],'<span class="up">较上一周期 +12.8%</span>','¥','data')}${kpi('有效订单',s[1],'排除退款、失效和重复订单','单','data')}${kpi('运营账号','24','<span class="danger">3 个异常</span> · 2 个养号中','号','accounts')}${kpi('待处理任务','7','<span class="danger">2 项临期</span> · 1 项逾期','✓','tasks')}</div><div class="dashboard-grid"><div class="card"><div class="card-head"><div><h3>${periodText[state.range]}收益与有效订单</h3></div><a data-action="goto" data-view="data">查看数据明细 →</a></div>${chart()}</div><div class="stack">${side}</div></div>`}

function dataView(){const base=summary[state.range],groups=['全部','A组','B组','C组'],owners=['全部','胡心玥','高宇芸','曾涛'],factor=activeDataFactor(),fmtCurrency=x=>money(Number(String(x).replace(/[¥,]/g,''))*factor);const s=[fmtCurrency(base[0]),Math.round(Number(String(base[1]).replace(/,/g,''))*factor).toLocaleString(),fmtCurrency(base[2]),base[3]];let rows=channelRows;if(state.dataGroup!=='全部')rows=rows.filter(x=>x.g===state.dataGroup);if(state.dataOwner!=='全部')rows=rows.filter(x=>ownerByGroup[x.g]===state.dataOwner);if(state.dataPlatform!=='全部')rows=rows.filter(x=>x.p===state.dataPlatform);if(state.dataBiz!=='全部')rows=rows.filter(x=>x.biz===state.dataBiz);if(state.dataSearch)rows=rows.filter(x=>x.pos.includes(state.dataSearch));const tableRows=rows.map((r,i)=>[`<span class="rank">${String(i+1).padStart(2,'0')}</span>`,`<div class="placement"><b>${r.pos}</b><span>${r.g} · ${ownerByGroup[r.g]} · ${r.p} · ${r.biz}</span></div>`,`<strong>${r.orders}</strong>`,money(r.gmv),money(r.commission),`<span class="rate">${r.rate}</span>`,r.aov,`<div class="share"><b>${r.share}%</b><i><span style="width:${r.share*2.8}%"></span></i></div>`,`<span class="${r.growth.startsWith('-')?'trend-down':'trend-up'}">${r.growth}</span>`,`<button class="detail-btn" data-action="placement-detail" data-pos="${r.pos}">查看详情</button>`]);const filterSummary=[state.dataGroup==='全部'?'全部渠道':state.dataGroup,state.dataOwner==='全部'?'全部负责人':state.dataOwner,state.dataPlatform==='全部'?'全部平台':state.dataPlatform,state.dataBiz==='全部'?'全部业务':state.dataBiz].join(' / ');const context=state.dataSource?`<div class="drill-context"><span>从员工中心带入：</span><strong>${state.dataOwner} · ${state.dataGroup}</strong><button data-action="clear-employee-filter">清除人员筛选</button></div>`:'';const groupCards=['A组','B组','C组'].map(g=>{const rs=channelRows.filter(r=>r.g===g),orders=rs.reduce((n,r)=>n+r.orders,0),commission=rs.reduce((n,r)=>n+r.commission,0);return `<button class="data-group-card ${state.dataGroup===g?'active':''}" data-action="data-group" data-group="${g}"><span>${g} · ${ownerByGroup[g]}</span><strong>${orders} 单</strong><small>${money(commission)} 预估佣金</small></button>`}).join('');const trend=state.dataTrendCollapsed?`<div class="trend-collapsed"><span>趋势图已收起，不影响下方明细筛选</span><button class="detail-btn" data-action="toggle-data-trend">展开趋势</button></div>`:`<div class="card trend-card compact"><div class="card-head"><div><h3>${periodText[state.range]}趋势</h3><p>所选周期按日展示；柱为订单，线为佣金</p></div><button class="ghost-btn" data-action="toggle-data-trend">收起</button></div>${chart(true)}</div>`;return `${pageLead('经营数据','先选渠道和时间，再查看指标、趋势及推广位明细','<span class="context-line">当前：<strong>'+filterSummary+'</strong></span>')}${context}<div class="data-toolbar"><div class="toolbar-cluster"><span class="toolbar-label">渠道</span><div class="channel-tabs">${groups.map(g=>`<button class="channel-tab ${state.dataGroup===g?'active':''}" data-action="data-group" data-group="${g}">${g==='全部'?'全部渠道':g}<i></i></button>`).join('')}</div></div><div class="toolbar-cluster period-cluster"><span class="toolbar-label">时间</span>${periodTabs(true)}</div></div><div class="kpi-grid five data-kpis">${kpi('有效订单',s[1],'<span class="danger">↓ 3.4%</span> 较前周期','单')}${kpi('预估佣金',s[0],'<span class="danger">↓ 1.6%</span> 较前周期','¥')}${kpi('成交金额',s[2],'<span class="danger">↓ 0.3%</span> 较前周期','额')}${kpi('平均客单价','¥73.92','按当前筛选范围统计','均')}${kpi('预估佣金率',s[3],'预估佣金 ÷ 成交金额','率')}</div><div class="data-insights-grid">${trend}<div class="card group-performance"><div class="card-head"><div><h3>各组表现</h3><p>横向对比渠道规模，点击后直接筛选明细</p></div></div><div class="data-group-cards">${groupCards}</div></div></div><div class="card ranking-card"><div class="ranking-heading"><div><h3>推广位表现排名</h3><p>${periodText[state.range]} · ${state.dataGroup==='全部'?'全部渠道':state.dataGroup} · 共 ${rows.length} 个推广位</p></div></div><div class="ranking-filterbar"><span>继续筛选</span><select class="select" data-action="data-owner">${owners.map(x=>`<option ${state.dataOwner===x?'selected':''}>${x==='全部'?'全部负责人':x}</option>`).join('')}</select><select class="select" data-action="data-platform"><option ${state.dataPlatform==='全部'?'selected':''}>全部平台</option>${['淘宝闪购','美团'].map(x=>`<option ${state.dataPlatform===x?'selected':''}>${x}</option>`).join('')}</select><select class="select" data-action="data-biz"><option ${state.dataBiz==='全部'?'selected':''}>全部业务</option>${['三福','名创优品','屈臣氏'].map(x=>`<option ${state.dataBiz===x?'selected':''}>${x}</option>`).join('')}</select><input class="search" data-action="data-search" value="${state.dataSearch}" placeholder="搜索推广位" /></div>${rows.length?table(['排名','推广位与归属','有效订单','成交金额','预估佣金','佣金率','客单价','订单贡献','增长趋势','详情'],tableRows,'ranking-table'):'<div class="empty">当前筛选下暂无推广位数据</div>'}</div>`}

function accounts(){const groups=['全部','A组','B组','C组','未分配'];const filtered=state.accountGroup==='全部'?accountsData:accountsData.filter(x=>x[1]===state.accountGroup);return `${pageLead('账号全生命周期','新增、养号、启用和异常处理分开管理','<button class="primary" data-action="add">＋ 新增账号</button>')}<div class="kpi-grid five account-kpis">${kpi('累计账号','31','包含历史停用账号','总',null,'neutral')}${kpi('正常运营','20','占当前运营账号 83%','常',null,'healthy')}${kpi('养号中','2','平均已养号 4 天','养',null,'warning')}${kpi('异常 / 封禁','3','近7天新增 1 个异常','!',null,'risk')}${kpi('近7天新增','4','其中 2 个尚未启用','新',null,'new')}</div><div class="split-grid" style="margin-bottom:17px"><div class="card"><div class="card-head"><div><h3>各组账号汇总</h3><p>用于快速判断账号资源主要分布在哪里</p></div></div><div class="group-summary"><button data-action="account-group" data-group="A组"><span>A组</span><b>11</b><small>正常 8 · 养号 1 · 异常 2</small></button><button data-action="account-group" data-group="B组"><span>B组</span><b>10</b><small>正常 7 · 养号 1 · 异常 1</small></button><button data-action="account-group" data-group="C组"><span>C组</span><b>8</b><small>正常 7 · 新增 1</small></button><button data-action="account-group" data-group="未分配"><span>未分配</span><b>2</b><small>需要分配组别和负责人</small></button></div></div><div class="card"><div class="card-head"><div><h3>近期异常事件</h3><p>优先关注违规、封号、实名和申诉</p></div></div><div class="alert-row"><i class="mini-dot"></i><div><strong>品牌观察站 · 违规限制</strong><span>09-23 · 胡心玥 · 申诉中</span></div></div><div class="alert-row"><i class="mini-dot yellow"></i><div><strong>每日好物推荐 · 弹实名</strong><span>09-22 · 曾涛 · 待处理</span></div></div></div></div><div class="card"><div class="card-head"><div><h3>账号清单</h3><p>按组查看，点击账号进入完整档案</p></div></div><div class="group-tabs">${groups.map(g=>`<button class="filter-btn ${state.accountGroup===g?'active':''}" data-action="account-group" data-group="${g}">${g}</button>`).join('')}</div>${table(['账号昵称','组别','生命周期','账号状态','负责人','启用 / 新增日期'],filtered.map(r=>r.map((c,j)=>j===0?`<span class="row-link" data-action="account-detail" data-index="${accountsData.indexOf(r)}">${c}</span>`:j===3?(c==='正常'?chip(c):chip(c,c==='违规处理中'?'red':'yellow')):c)))}</div>`}

function business(){const tabs=[['active','正在进行'],['upcoming','即将开始'],['ended','历史结果'],['all','全部活动']];let list=state.activityView==='all'?incentiveActivities:incentiveActivities.filter(x=>x.phase===state.activityView);const card=a=>`<article class="activity-card ${a.phase==='upcoming'||a.status.includes('结束')?'focus':''}"><div class="activity-title"><h3>${a.name}</h3>${chip(a.status,a.phase==='upcoming'?'yellow':a.status.includes('结束')?'red':'')}</div><div class="activity-meta">活动时间：${a.start}—${a.end}</div><div class="activity-metrics"><div><span>当前有效订单</span><b>${a.orders}</b></div><div><span>下一目标</span><b>${a.target}</b></div><div><span>激励标准</span><b>${a.bonus}</b></div></div>${a.phase==='upcoming'?`<div class="upcoming-policy"><span>活动要求</span><strong>${a.requirement}</strong></div>`:`<div class="context-line"><span>门槛进度</span><strong style="margin-left:auto">距下一档 ${Math.max(0,a.target-a.orders)} 单</strong></div><div class="progress"><span style="width:${Math.min(100,a.orders/a.target*100)}%"></span></div><div class="threshold"><div class="tier active"><b>200单</b><span>¥1.5/单</span></div><div class="tier ${a.orders>=400?'active':''}"><b>400单</b><span>¥2.0/单</span></div><div class="tier ${a.orders>=500?'active':''}"><b>500单</b><span>¥2.5/单</span></div></div>`}<button class="detail-btn activity-detail-btn" data-action="activity-detail" data-id="${a.id}">查看活动要求与数据</button></article>`;const endedRows=incentiveActivities.filter(x=>x.phase==='ended').map(a=>[a.name,`${a.start}—${a.end}`,a.orders,a.bonus,a.accounts,a.notes,`<button class="detail-btn" data-action="activity-detail" data-id="${a.id}">查看总结</button>`]);let content;if(state.activityView==='ended')content=`<div class="card history-card"><div class="card-head"><div><h3>已结束活动汇总</h3><p>活动结束后保留订单、预估激励、启用账号和发布笔记</p></div></div>${table(['活动名称','活动时间','有效订单','预估激励','启用账号','发布笔记','活动总结'],endedRows)}</div>`;else if(state.activityView==='all')content=`<div class="activity-list">${list.filter(x=>x.phase!=='ended').map(card).join('')}</div><div class="card history-card"><div class="card-head"><div><h3>已结束活动</h3><p>历史结果单独归档，不与进行中卡片混在一起</p></div></div>${table(['活动名称','活动时间','有效订单','预估激励','启用账号','发布笔记','活动总结'],endedRows)}</div>`;else content=`<div class="activity-list">${list.map(card).join('')}</div>`;return `${pageLead('激励活动中心','只管理活动时间、激励政策、订单门槛和活动结果','<button class="primary" data-action="add">＋ 新增激励活动</button>')}<div class="business-alerts"><div class="business-alert"><span>明天开始</span><strong>三福秋季上新</strong><small>09/24—10/10 · 最高 ¥2.5/单</small></div><div class="business-alert green"><span>正在冲刺</span><strong>名创距下一档 108 单</strong><small>当前 392 单 · 09/30 结束</small></div><div class="business-alert red"><span>即将结束</span><strong>屈臣氏会员周</strong><small>明天结束 · 已达到第二档</small></div></div><div class="view-tabs activity-tabs">${tabs.map(([k,v])=>`<button class="view-tab ${state.activityView===k?'active':''}" data-action="activity-view" data-filter="${k}">${v}</button>`).join('')}</div>${content}`}

function taskStatusSelect(task,i){return `<select class="status-select" data-action="task-status" data-index="${i}">${['未开始','进行中','已完成','已取消'].map(s=>`<option ${task.status===s?'selected':''}>${s}</option>`).join('')}</select>`}
function tasksView(){const owners=['全部','胡心玥','高宇芸','曾涛'];let rows=tasks.map((t,i)=>({...t,index:i}));if(state.taskFilter==='mine')rows=rows.filter(t=>t.owner==='胡心玥');if(state.taskFilter==='risk')rows=rows.filter(t=>['临期','已逾期'].includes(t.alert));if(state.taskOwner!=='全部')rows=rows.filter(t=>t.owner===state.taskOwner);const items=rows.map(t=>{const warning=t.alert==='已逾期'?chip(t.alert,'red'):t.alert==='临期'?chip(t.alert,'yellow'):t.alert==='已完成'?chip(t.alert):chip('正常','blue');const expanded=state.taskExpanded===String(t.index);const progress=t.progress==null?'':`<div class="task-progress-inline"><span>自报进度 ${t.progress}%</span><div class="progress"><span style="width:${t.progress}%"></span></div></div>`;return `<article class="task-item ${expanded?'expanded':''}"><div class="task-item-main"><div class="task-name"><strong>${t.name}</strong><span>${t.module} · ${t.owner}</span></div><div><span>截止时间</span><strong>${t.end}</strong></div><div>${warning}</div><div class="task-status-wrap">${taskStatusSelect(t,t.index)}</div><button class="task-expand" data-action="task-detail" data-index="${t.index}">${expanded?'收起':'查看进展'} ${expanded?'⌃':'⌄'}</button></div>${expanded?`<div class="task-detail-panel"><div><span>任务说明</span><p>${t.note}</p></div><div><span>最近进展汇报</span><p>${t.report}</p>${progress}</div><div><span>管理提示</span><p>${t.progress==null?'当前任务没有客观百分比，按文字汇报判断进展。':'该百分比由执行人填写，应结合文字汇报判断。'}</p></div></div>`:''}</article>`}).join('');return `${pageLead('任务中心','先看状态和截止时间；长线任务点开后查看文字进展','<button class="primary" data-action="add">＋ 新建任务</button>')}<div class="kpi-grid task-kpis">${kpi('进行中','3','员工已确认开始处理','进')}${kpi('未开始','1','等待执行人确认','未')}${kpi('临期','2','24小时内到期','期',null,'warning')}${kpi('已逾期','1','未完成且超过截止时间','!',null,'risk')}</div><div class="card task-list-card"><div class="card-head task-head"><div><h3>任务明细</h3><p>进度百分比不作为核心判断，优先查看状态、时间和文字汇报</p></div><div class="task-controls"><div class="view-tabs"><button class="view-tab ${state.taskFilter==='all'?'active':''}" data-action="task-filter" data-filter="all">全部</button><button class="view-tab ${state.taskFilter==='mine'?'active':''}" data-action="task-filter" data-filter="mine">我负责的</button><button class="view-tab ${state.taskFilter==='risk'?'active':''}" data-action="task-filter" data-filter="risk">临期 / 逾期</button></div><select class="select" data-action="task-owner">${owners.map(o=>`<option ${state.taskOwner===o?'selected':''}>${o==='全部'?'全部负责人':o}</option>`).join('')}</select></div></div><div class="task-list">${items}</div></div><div class="task-rules compact-rules"><div><strong>工作状态</strong><span>由执行人填写：未开始、进行中、已完成、已取消</span></div><div><strong>时间提醒</strong><span>由系统计算：正常、临期、已逾期</span></div><div><strong>进展汇报</strong><span>长线任务填写文字进展；百分比仅作辅助</span></div></div>`}

function employeeDetail(e){const accountBase=Math.max(1,e.accounts),noteBase=Math.max(1,e.notes),perDay=e.accounts?(e.d7/accountBase/7).toFixed(2):'—',perNote=e.notes?(e.d30/noteBase).toFixed(2):'—',notesPerAccount=e.accounts?(e.notes/accountBase).toFixed(1):'—';return `<div class="employee-detail"><div class="detail-box"><h4>${e.status==='离职'?'历史账号归属':`负责账号（${e.accounts}）`}</h4><p>${e.list}</p>${e.status==='离职'?'':`<a class="text-link" data-action="employee-accounts" data-group="${e.group}">查看 ${e.group} 全部账号 →</a>`}</div><div class="detail-box"><h4>${e.status==='离职'?'任职记录':`当前任务（${e.tasks}）`}</h4><p>${e.status==='离职'?`${e.joined} 入职 · ${e.left} 离职`:e.task}</p>${e.status==='离职'?'':`<div class="task-progress"><div class="progress"><span style="width:${e.progress}%"></span></div><span>${e.progress}%</span></div>`}</div><div class="detail-box efficiency-box"><h4>${e.status==='离职'?'历史产出留存':'账号产出效率'}</h4><p><b>${perDay==='—'?'—':`¥${perDay}`}</b> 近7天单账号日均佣金</p><p><b>${perNote==='—'?'—':`¥${perNote}`}</b> 近30天单篇笔记佣金</p><p><b>${notesPerAccount}${notesPerAccount==='—'?'':'篇'}</b> 近30天单账号笔记数</p><a class="text-link" data-action="employee-data" data-name="${e.name}" data-group="${e.group}" data-range="30d">查看 ${e.name} 的完整经营数据 →</a></div></div>`}
function employeesView(){return `${pageLead('员工中心','以员工为入口汇总账号、笔记、佣金、任务和账号产出效率','<span class="context-line">点击佣金可直接查看该员工和所属组的数据</span>')}<div class="employee-list">${employees.map(e=>`<article class="employee-card"><div class="employee-summary enhanced" data-action="employee" data-name="${e.name}"><div class="employee-main"><div class="employee-avatar">${e.name.slice(-1)}</div><div><strong>${e.name}</strong><span>${e.group} · 账号负责人</span></div></div><div class="employee-stat"><span>负责账号</span><b>${e.accounts}</b></div><div class="employee-stat"><span>近30天笔记</span><b>${e.notes}</b></div><button class="employee-stat metric-link" data-action="employee-data" data-name="${e.name}" data-group="${e.group}" data-range="7d"><span>近7天佣金 ↗</span><b>¥${e.d7.toLocaleString()}</b></button><button class="employee-stat metric-link" data-action="employee-data" data-name="${e.name}" data-group="${e.group}" data-range="7d"><span>单账号日均 ↗</span><b>¥${(e.d7/e.accounts/7).toFixed(0)}</b></button><div class="employee-stat"><span>进行中任务</span><b>${e.tasks}</b></div><span>${state.employee===e.name?'⌃':'⌄'}</span></div>${state.employee===e.name?employeeDetail(e):''}</article>`).join('')}</div>`}

