function experiments(){
  let rows=experimentRows;if(state.experimentStatus!=='全部')rows=rows.filter(x=>x.status===state.experimentStatus);
  const cards=rows.map(x=>`<article class="experiment-card"><div class="experiment-head"><div><span class="eyebrow">${x.id.toUpperCase()}</span><h3>${x.name}</h3><p>${x.target}</p></div>${chip(x.status,x.status==='已完成'?'green':x.status==='待复盘'?'yellow':'blue')}</div><div class="experiment-logic"><div><span>测试假设</span><strong>${x.hypothesis}</strong></div><div><span>判断标准</span><strong>${x.baseline} → ${x.goal}</strong></div></div><div class="experiment-meta"><span>${x.owner}</span><span>${x.start}—${x.end}</span><span>密令：${x.secret}</span></div><div class="experiment-result"><span>当前结果</span><strong>${x.result}</strong><p>${x.conclusion}</p></div><div class="experiment-actions"><button class="detail-btn" data-action="experiment-detail" data-id="${x.id}">查看完整记录</button><button class="ghost-btn" data-action="experiment-task" data-owner="${x.owner}">关联任务：${x.task}</button></div></article>`).join('');
  return `${pageLead('业务测试','把想法、执行过程、判断标准和最终结论放在同一条可追溯记录里','<button class="primary" data-action="new-experiment">＋ 新建测试</button>')}<div class="kpi-grid experiment-kpis">${kpi('进行中','1','正在采集样本','试')}${kpi('待复盘','1','已有结果，等待结论','析',null,'warning')}${kpi('已完成','1','结论已沉淀','成',null,'healthy')}${kpi('关联任务','2','执行人与截止时间已明确','任')}</div><div class="experiment-toolbar"><div class="view-tabs">${['全部','进行中','待复盘','已完成'].map(x=>`<button class="view-tab ${state.experimentStatus===x?'active':''}" data-action="experiment-status" data-status="${x}">${x}</button>`).join('')}</div><span>测试结果只用于业务判断，不替代正式财务口径</span></div><div class="experiment-grid">${cards}</div>`;
}
function experimentDetail(id){
  const x=experimentRows.find(row=>row.id===id);openDrawer(x.name,`<div class="drawer-section"><div class="drawer-kpis"><div><span>负责人</span><b>${x.owner}</b></div><div><span>测试周期</span><b>${x.start}—${x.end}</b></div><div><span>当前状态</span><b>${x.status}</b></div></div></div><div class="drawer-section"><h3>要验证什么</h3><p>${x.target}</p><p><strong>假设：</strong>${x.hypothesis}</p></div><div class="drawer-section"><h3>关联业务</h3>${table(['类型','内容'],[['激励活动',x.activity],['使用密令',x.secret],['执行任务',x.task]])}</div><div class="drawer-section"><h3>结果与结论</h3><p><strong>${x.result}</strong></p><p>${x.conclusion}</p></div>`);
}
