  const trs=rows.map(x=>{const meta=secretMeta[x.word]||{tags:[],note:''},trend=secretTrend[x.word]||[0,0,0,0,0,0,0],total=trend.reduce((n,v)=>n+v,0),history=secretAssignments.filter(a=>a.word===x.word).length;return [`<button class="row-link secret-word" data-action="secret-detail" data-word="${x.word}">${x.word}</button><small>${x.biz}-业务帖-${x.word} · ${history?'归属记录 '+history+' 条':meta.note}</small>`,x.platform,x.biz,x.group,x.owner,`<div class="tag-list">${meta.tags.map(t=>chip(t,t==='临期'||t==='停用'||t==='待续期'?'red':'blue')).join('')}</div>`,`<div class="secret-trend">${sparkline(trend,x.days<0?'#d95b62':'#4f75f3')}<b>近7天 ${total} 单</b></div>`,x.expiry,x.days<0?chip(`已到期 ${Math.abs(x.days)} 天`,'red'):x.days<=3?chip(x.days===0?'今天到期':`${x.days}天后到期`,'red'):chip('有效')];});
