function accounts(){
  const groups=['全部','A组','B组','C组','未分配'],filtered=state.accountGroup==='全部'?accountsData:accountsData.filter(x=>x[1]===state.accountGroup);
  const distribution=[
    {group:'A组',owner:'胡心玥',total:11,normal:8,cultivate:1,risk:2,color:'#5276d9'},
    {group:'B组',owner:'高宇芸',total:10,normal:7,cultivate:1,risk:1,newCount:1,color:'#745cc8'},
    {group:'C组',owner:'曾涛',total:8,normal:7,cultivate:0,risk:0,newCount:1,color:'#2d9671'},
    {group:'未分配',owner:'待分配',total:2,normal:0,cultivate:0,risk:0,newCount:2,color:'#a4adbb'}
  ];
  const rows=distribution.map(g=>`<button class="account-group-row ${state.accountGroup===g.group?'active':''}" data-action="account-group" data-group="${g.group}"><span class="group-orb" style="--group-color:${g.color}">${g.group==='未分配'?'—':g.group.slice(0,1)}</span><span class="group-identity"><strong>${g.group}</strong><small>${g.owner}</small></span><span class="group-total"><b>${g.total}</b><small>账号</small></span><span class="account-stack"><i class="normal" style="width:${g.total?g.normal/g.total*100:0}%"></i><i class="cultivate" style="width:${g.total?g.cultivate/g.total*100:0}%"></i><i class="risk" style="width:${g.total?g.risk/g.total*100:0}%"></i><i class="new" style="width:${g.total?(g.newCount||0)/g.total*100:0}%"></i></span><span class="group-breakdown">正常 ${g.normal} · 养号 ${g.cultivate} · 异常 ${g.risk} · 新增 ${g.newCount||0}</span><span class="row-chevron">›</span></button>`).join('');
  return `${pageLead('账号全生命周期','新增、养号、启用和异常处理分开管理','<button class="primary" data-action="add">＋ 新增账号</button>')}<div class="kpi-grid five account-kpis">${kpi('累计账号','31','包含历史停用账号','总',null,'neutral')}${kpi('正常运营','20','占当前运营账号 83%','常',null,'healthy')}${kpi('养号中','2','平均已养号 4 天','养',null,'warning')}${kpi('异常 / 封禁','3','近7天新增 1 个异常','!',null,'risk')}${kpi('近7天新增','4','其中 2 个尚未启用','新',null,'new')}</div><div class="account-overview-grid"><div class="card account-distribution-card"><div class="card-head"><div><h3>各组账号分布</h3><p>点击组别直接筛选下方账号清单</p></div><div class="account-legend"><span><i class="normal"></i>正常</span><span><i class="cultivate"></i>养号</span><span><i class="risk"></i>异常</span><span><i class="new"></i>新增</span></div></div><div class="account-group-list">${rows}</div></div><div class="card account-alert-card"><div class="card-head"><div><h3>近期异常</h3><p>优先处理影响运营的账号</p></div></div><div class="alert-row"><i class="mini-dot"></i><div><strong>品牌观察站 · 违规限制</strong><span>09-23 · 胡心玥 · 申诉中</span></div></div><div class="alert-row"><i class="mini-dot yellow"></i><div><strong>每日好物推荐 · 弹实名</strong><span>09-22 · 曾涛 · 待处理</span></div></div></div></div><div class="card"><div class="card-head"><div><h3>账号清单</h3><p>${state.accountGroup==='全部'?'全部组别':state.accountGroup} · 共 ${filtered.length} 条示例记录</p></div></div><div class="group-tabs">${groups.map(g=>`<button class="filter-btn ${state.accountGroup===g?'active':''}" data-action="account-group" data-group="${g}">${g}</button>`).join('')}</div>${table(['账号昵称','组别','生命周期','账号状态','负责人','启用 / 新增日期'],filtered.map(r=>r.map((c,j)=>j===0?`<span class="row-link" data-action="account-detail" data-index="${accountsData.indexOf(r)}">${c}</span>`:j===3?(c==='正常'?chip(c):chip(c,c==='违规处理中'?'red':'yellow')):c)))}</div>`;
}

function taskTime(value,empty='—'){return value||empty}
function tasksView(){
  const owners=['全部','胡心玥','高宇芸','曾涛'];let rows=tasks.map((t,i)=>({...t,index:i}));
  if(state.taskView==='active')rows=rows.filter(t=>!['已完成','已取消'].includes(t.status));
  if(state.taskView==='history')rows=rows.filter(t=>['已完成','已取消'].includes(t.status)).sort((a,b)=>(b.actualEnd||b.end).localeCompare(a.actualEnd||a.end));
  if(state.taskView==='risk')rows=rows.filter(t=>['临期','已逾期'].includes(t.alert));
  if(state.taskOwner!=='全部')rows=rows.filter(t=>t.owner===state.taskOwner);
  const items=rows.map(t=>{const warning=t.alert==='已逾期'?chip(t.alert,'red'):t.alert==='临期'?chip(t.alert,'yellow'):t.alert==='已完成'?chip(t.alert):chip('正常','blue'),expanded=state.taskExpanded===String(t.index);return `<article class="task-item timeline-task ${expanded?'expanded':''}"><div class="task-item-main timeline-main"><div class="task-name"><strong>${t.name}</strong><span>${t.module} · ${t.owner}</span><small class="task-mobile-times">${taskTime(t.start)} → ${taskTime(t.end)}${t.actualEnd?` · 完成 ${t.actualEnd}`:''}</small></div><div class="task-time"><span>开始</span><strong>${taskTime(t.start)}</strong></div><div class="task-time"><span>截止</span><strong>${taskTime(t.end)}</strong></div><div class="task-time"><span>实际完成</span><strong>${taskTime(t.actualEnd,'尚未完成')}</strong></div><div>${warning}</div><div class="task-status-wrap">${taskStatusSelect(t,t.index)}</div><button class="task-expand" data-action="task-detail" data-index="${t.index}">${expanded?'收起':'查看记录'} ${expanded?'⌃':'⌄'}</button></div>${expanded?`<div class="task-detail-panel"><div><span>任务说明</span><p>${t.note}</p></div><div><span>历史进展</span><p>${t.report}</p></div><div><span>时间结果</span><p>${t.actualEnd?`实际完成：${t.actualEnd}`:'完成后自动写入实际完成时间'}</p></div></div>`:''}</article>`}).join('');
  return `${pageLead('任务中心','按进行中、风险和历史归档查看；时间节点完整保留','<button class="primary" data-action="add">＋ 新建任务</button>')}<div class="kpi-grid task-kpis">${kpi('进行中',String(tasks.filter(t=>t.status==='进行中').length),'员工已确认开始','进')}${kpi('未开始',String(tasks.filter(t=>t.status==='未开始').length),'等待执行人确认','未')}${kpi('临期 / 逾期',String(tasks.filter(t=>['临期','已逾期'].includes(t.alert)).length),'需要负责人关注','期',null,'risk')}${kpi('历史归档',String(tasks.filter(t=>['已完成','已取消'].includes(t.status)).length),'完成和取消都保留','史',null,'neutral')}</div><div class="card task-list-card"><div class="card-head task-head"><div><h3>${state.taskView==='history'?'历史任务':'任务清单'}</h3><p>默认查看未完成任务；完成后进入历史，不会从系统中消失</p></div><div class="task-controls"><div class="view-tabs"><button class="view-tab ${state.taskView==='active'?'active':''}" data-action="task-view" data-filter="active">进行中</button><button class="view-tab ${state.taskView==='all'?'active':''}" data-action="task-view" data-filter="all">全部</button><button class="view-tab ${state.taskView==='risk'?'active':''}" data-action="task-view" data-filter="risk">临期 / 逾期</button><button class="view-tab ${state.taskView==='history'?'active':''}" data-action="task-view" data-filter="history">历史归档</button></div><select class="select" data-action="task-owner">${owners.map(o=>`<option ${state.taskOwner===o?'selected':''}>${o==='全部'?'全部负责人':o}</option>`).join('')}</select></div></div><div class="task-list">${items||'<div class="empty">当前分类暂无任务</div>'}</div></div>`;
}

function experiments(){
  let rows=experimentRows;if(state.experimentStatus!=='全部')rows=rows.filter(x=>x.status===state.experimentStatus);
  const cards=rows.map(x=>`<article class="experiment-card structured"><div class="experiment-head"><div><span class="eyebrow">${x.type} · ${x.id.toUpperCase()}</span><h3>${x.name}</h3><p><b>验证目标：</b>${x.target}</p></div>${chip(x.status,x.status==='已完成'?'green':x.status==='待复盘'?'yellow':'blue')}</div><div class="experiment-standard"><div><span>实验假设</span><strong>${x.hypothesis}</strong></div><div><span>核心指标</span><strong>${x.metric} · ${x.baseline} → ${x.goal}</strong></div></div><div class="ab-preview"><div class="ab-group a"><span>A</span><div><strong>${x.groupA.name}</strong><small>${x.groupA.accounts}</small><em>密令：${x.groupA.secret}</em></div></div><div class="ab-divider">对比</div><div class="ab-group b"><span>B</span><div><strong>${x.groupB.name}</strong><small>${x.groupB.accounts}</small><em>密令：${x.groupB.secret}</em></div></div></div><div class="experiment-result"><span>阶段结果</span><strong>${x.result}</strong><p>${x.conclusion}</p></div><div class="experiment-actions"><button class="detail-btn" data-action="experiment-detail" data-id="${x.id}">查看实验档案</button><button class="ghost-btn" data-action="experiment-task" data-owner="${x.owner}">查看执行任务</button></div></article>`).join('');
  return `${pageLead('业务测试','用标准化实验记录管理方案、样本账号、密令、指标和结论','<button class="primary" data-action="new-experiment">＋ 新建实验</button>')}<div class="experiment-guide"><strong>支持的测试方式</strong><span>A/B 对照：两组同期比较</span><span>前后对比：同一批账号调整前后比较</span><span>分时段对照：不同发布时间或周期比较</span></div><div class="experiment-toolbar"><div class="view-tabs">${['全部','进行中','待复盘','已完成'].map(x=>`<button class="view-tab ${state.experimentStatus===x?'active':''}" data-action="experiment-status" data-status="${x}">${x}</button>`).join('')}</div><span>执行任务用于明确负责人、开始时间和截止时间</span></div><div class="experiment-grid">${cards}</div>`;
}
function experimentDetail(id){const x=experimentRows.find(row=>row.id===id);openDrawer(x.name,`<div class="drawer-section"><div class="drawer-kpis"><div><span>实验类型</span><b>${x.type}</b></div><div><span>负责人</span><b>${x.owner}</b></div><div><span>周期</span><b>${x.start}—${x.end}</b></div></div></div><div class="drawer-section"><h3>研究设计</h3><p><strong>验证目标：</strong>${x.target}</p><p><strong>实验假设：</strong>${x.hypothesis}</p><p><strong>核心指标：</strong>${x.metric} · ${x.baseline} → ${x.goal}</p></div><div class="drawer-section"><h3>对照方案</h3><div class="ab-detail"><div><b>A</b><strong>${x.groupA.name}</strong><span>${x.groupA.strategy}</span><span>账号：${x.groupA.accounts}</span><span>密令：${x.groupA.secret}</span></div><div><b>B</b><strong>${x.groupB.name}</strong><span>${x.groupB.strategy}</span><span>账号：${x.groupB.accounts}</span><span>密令：${x.groupB.secret}</span></div></div></div><div class="drawer-section"><h3>实验结果</h3><p><strong>${x.result}</strong></p><p>${x.conclusion}</p></div>`)}

function newExperimentDrawer(){openDrawer('新建标准化实验',`<form id="new-experiment-form" class="drawer-form"><label>实验名称<input name="name" required placeholder="例如：商品图与场景图首图对照" /></label><label>验证目标<textarea name="target" rows="2" required placeholder="要验证的业务问题和预期用途"></textarea></label><label>实验假设<textarea name="hypothesis" rows="2" required placeholder="方案变化预计会影响哪个指标"></textarea></label><div class="form-two"><label>测试类型<select name="type"><option>A/B 对照实验</option><option>前后对比实验</option><option>分时段对照</option></select></label><label>核心指标<input name="metric" required placeholder="例如：单篇有效订单" /></label></div><div class="ab-form"><h4>A 组方案</h4><input name="aStrategy" required placeholder="A组执行方案" /><input name="aAccounts" required placeholder="A组账号，多个用顿号分隔" /><select name="aSecret">${secretRows.map(x=>`<option>${x.word}</option>`).join('')}</select></div><div class="ab-form"><h4>B 组方案</h4><input name="bStrategy" required placeholder="B组执行方案" /><input name="bAccounts" required placeholder="B组账号，多个用顿号分隔" /><select name="bSecret">${secretRows.map(x=>`<option>${x.word}</option>`).join('')}</select></div><div class="form-two"><label>负责人<select name="owner"><option>胡心玥</option><option>高宇芸</option><option>曾涛</option></select></label><label>判断标准<input name="goal" required placeholder="例如：提升 20%" /></label></div><div class="form-two"><label>开始时间<input name="start" type="date" required /></label><label>计划结束<input name="end" type="date" required /></label></div><label class="check-row"><input name="createTask" type="checkbox" checked /> 同时创建一条执行任务</label><button class="primary form-submit" type="submit">保存实验</button></form>`)}

function employeesView(){
  const filtered=employees.filter(e=>state.employeeStatus==='全部'||e.status===state.employeeStatus);
  return `${pageLead('员工中心','人员发生新增、转组或离职时保留历史归属和历史业绩','<button class="primary" data-action="employee-entry">＋ 员工档案</button>')}<div class="employee-master-note"><div><strong>员工主表是唯一人员档案</strong><span>中台和飞书修改的是同一条员工记录；账号、任务、笔记和佣金通过员工 ID 自动关联。</span></div><div><strong>离职不删除</strong><span>状态改为离职并停止新增归属，历史账号和业绩仍可查询。</span></div></div><div class="employee-statusbar"><div class="view-tabs">${['在职','离职','全部'].map(x=>`<button class="view-tab ${state.employeeStatus===x?'active':''}" data-action="employee-status" data-status="${x}">${x}</button>`).join('')}</div><span>在职 ${employees.filter(e=>e.status==='在职').length} 人 · 离职档案 ${employees.filter(e=>e.status==='离职').length} 人</span></div><div class="employee-list">${filtered.map(e=>`<article class="employee-card ${e.status==='离职'?'former':''}"><div class="employee-summary enhanced" data-action="employee" data-name="${e.name}"><div class="employee-main"><div class="employee-avatar">${e.name.slice(-1)}</div><div><strong>${e.name} ${e.status==='离职'?chip('已离职','red'):''}</strong><span>${e.group} · ${e.joined} 入职${e.left?` · ${e.left} 离职`:''}</span></div></div><div class="employee-stat"><span>${e.status==='离职'?'历史负责账号':'负责账号'}</span><b>${e.accounts}</b></div><div class="employee-stat"><span>历史累计笔记</span><b>${e.notes}</b></div><button class="employee-stat metric-link" data-action="employee-data" data-name="${e.name}" data-group="${e.group}" data-range="30d"><span>${e.status==='离职'?'离职前30天佣金':'近30天佣金'} ↗</span><b>¥${e.d30.toLocaleString()}</b></button><div class="employee-stat"><span>当前任务</span><b>${e.tasks}</b></div><span>${state.employee===e.name?'⌃':'⌄'}</span></div>${state.employee===e.name?employeeDetail(e):''}</article>`).join('')}</div>`;
}
function employeeEntryDrawer(){openDrawer('员工档案入口',`<form id="employee-form" class="drawer-form"><div class="notice compact-notice"><span>这里新增或在飞书员工主表新增都可以；正式双向同步后会落到同一个员工 ID，避免重复人员。</span></div><label>员工姓名<input name="name" required /></label><div class="form-two"><label>所属组<select name="group"><option>A组</option><option>B组</option><option>C组</option><option>待分组</option></select></label><label>人员状态<select name="status"><option>在职</option><option>离职</option></select></label></div><label>入职日期<input name="joined" type="date" required /></label><button class="primary form-submit" type="submit">保存员工档案</button></form>`)}

function orders(){
  const insights=productInsights[state.orderScope],latest=orderBatches[0];
  const cards=insights.map((x,i)=>`<article class="product-insight-card"><div class="product-rank">0${i+1}</div><div><span>${x.biz}</span><h3>${x.product}</h3><p>${x.note}</p></div><div class="product-number"><strong>${x.orders}</strong><span>订单 · 占该业务 ${x.share}%</span></div></article>`).join('');
  return `${pageLead('订单分析','分析用户主要购买的商品类型，并管理每次手工导入的日期范围','<button class="primary" data-action="order-import">＋ 导入订单数据</button>')}<div class="import-status"><div><span>当前数据覆盖</span><strong>${orderBatches[orderBatches.length-1].start}—${latest.end}</strong><small>共 ${orderBatches.length} 个导入批次</small></div><div><span>最近一次导入</span><strong>${latest.name}</strong><small>${latest.imported} · ${latest.rows.toLocaleString()} 条</small></div><div class="import-warning"><span>下次建议导入</span><strong>2026-10-01 开始的数据</strong><small>系统会检查与历史批次是否重叠</small></div></div><div class="view-tabs order-scope-tabs"><button class="view-tab ${state.orderScope==='latest'?'active':''}" data-action="order-scope" data-scope="latest">最新导入批次</button><button class="view-tab ${state.orderScope==='all'?'active':''}" data-action="order-scope" data-scope="all">历史累计数据</button></div><div class="card product-analysis"><div class="card-head"><div><h3>${state.orderScope==='latest'?'9月最新批次':'7—9月累计'}商品购买偏好</h3><p>当前订单明细可见范围内，按业务汇总出现最多的商品类型</p></div></div><div class="product-insight-grid">${cards}</div></div><div class="card import-history"><div class="card-head"><div><h3>订单导入记录</h3><p>每次保留导入日期、数据范围、条数和操作人，避免重复日期</p></div><button class="detail-btn" data-action="order-import">登记新批次</button></div>${table(['批次名称','订单日期范围','数据条数','导入时间','操作人','状态'],orderBatches.map(x=>[x.name,`${x.start}—${x.end}`,x.rows.toLocaleString(),x.imported,x.user,chip(x.status,'green')]),'import-table')}</div>`;
}
function orderImportDrawer(){openDrawer('导入订单数据',`<form id="order-import-form" class="drawer-form"><div class="danger-note neutral-note"><strong>先确认日期范围</strong><span>系统会与历史导入批次比较；发现日期重叠时将阻止保存，避免重复统计。</span></div><label>批次名称<input name="name" required placeholder="例如：10月订单明细" /></label><div class="form-two"><label>订单开始日期<input name="start" type="date" required /></label><label>订单结束日期<input name="end" type="date" required /></label></div><label>订单文件<input name="file" type="file" accept=".xlsx,.xls,.csv" /></label><label>备注<textarea name="note" rows="3" placeholder="记录数据来源或缺失情况"></textarea></label><button class="primary form-submit" type="submit">校验范围并登记批次</button></form>`)}

function business(){
  const tabs=[['active','进行中'],['upcoming','即将开始'],['ended','已结算'],['all','全部活动']];let list=state.activityView==='all'?incentiveActivities:incentiveActivities.filter(x=>x.phase===state.activityView);
  const card=a=>{const model=activityModels[a.id]||activityModels['act-01'],current=a.phase==='ended'?(model.metric==='gmv'?model.current:a.orders):model.current,ratio=Math.round(current/model.target*100),daily=activityMetricDaily[a.id]||[0,0,0,0,0,0,0];return `<article class="activity-card ${a.phase==='upcoming'?'focus':''}"><div class="activity-title"><div><span class="metric-badge">按${model.label}计算</span><h3>${a.name}</h3></div>${chip(a.status,a.phase==='upcoming'?'yellow':a.phase==='ended'?'green':'')}</div><div class="activity-meta">活动时间：${a.start}—${a.end}</div><div class="activity-metrics"><div><span>当前${model.label}</span><b>${formatMetric(model,current)}</b></div><div><span>目标门槛</span><b>${formatMetric(model,model.target)}</b></div><div><span>激励规则</span><b>${model.reward}</b></div></div>${a.phase==='upcoming'?`<div class="upcoming-policy"><span>活动要求</span><strong>${a.requirement}</strong></div>`:`<div class="activity-daily"><div><span>近7天${model.label}</span><strong>${formatMetric(model,daily.reduce((n,v)=>n+v,0))}</strong></div>${sparkline(daily,'#e6aa2d')}</div><div class="context-line"><span>门槛进度</span><strong style="margin-left:auto">${ratio}% · 距门槛 ${formatMetric(model,Math.max(0,model.target-current))}</strong></div><div class="progress"><span style="width:${Math.min(100,ratio)}%"></span></div>`}<div class="activity-card-actions"><button class="detail-btn" data-action="activity-detail" data-id="${a.id}">查看要求与数据</button>${a.phase==='active'?`<button class="settle-btn" data-action="settle-activity" data-id="${a.id}">活动结算</button>`:''}</div></article>`};
  const endedRows=incentiveActivities.filter(x=>x.phase==='ended').map(a=>{const m=activityModels[a.id]||activityModels['act-01'];return [a.name,a.status,m.label,formatMetric(m,m.metric==='gmv'?m.current:a.orders),a.bonus,`<button class="detail-btn" data-action="activity-detail" data-id="${a.id}">查看结算</button>`]});let content;
  if(state.activityView==='ended')content=`<div class="card history-card">${table(['活动名称','结束方式','统计口径','最终业绩','最终激励','结算档案'],endedRows)}</div>`;
  else if(state.activityView==='all')content=`<div class="activity-list">${list.filter(x=>x.phase!=='ended').map(card).join('')}</div><div class="card history-card">${table(['活动名称','结束方式','统计口径','最终业绩','最终激励','结算档案'],endedRows)}</div>`;
  else content=`<div class="activity-list">${list.map(card).join('')}</div>`;
  return `${pageLead('激励活动中心','订单型与 GMV 型活动使用不同门槛；所有结束方式统一进入结算','<button class="primary" data-action="add">＋ 新增激励活动</button>')}<div class="settlement-rule"><div><strong>正常到期</strong><span>到达结束日期后自动标记“待结算”，并创建结算任务；确认最终数据后归档。</span></div><div><strong>提前停止</strong><span>外部先达到总量或平台提前终止时，立即进入同一结算表单。</span></div><div><strong>最终留存</strong><span>保存结束方式、统计口径、最终业绩、激励金额和确认人。</span></div></div><div class="view-tabs activity-tabs">${tabs.map(([k,v])=>`<button class="view-tab ${state.activityView===k?'active':''}" data-action="activity-view" data-filter="${k}">${v}</button>`).join('')}</div>${content}`;
}
function settlementDrawer(id){const a=incentiveActivities.find(x=>x.id===id),m=activityModels[id]||activityModels['act-01'],value=m.metric==='gmv'?m.current:a.orders,ratio=Math.round(value/m.target*100);openDrawer(`活动结算 · ${a.name}`,`<form id="settlement-form" class="drawer-form" data-id="${a.id}"><div class="settlement-type"><span>统计口径</span><strong>${m.label}</strong><small>${m.reward}</small></div><label>结束方式<select name="reason"><option>活动按计划正常结束</option><option>外部总量已先达到活动上限</option><option>平台提前结束活动</option><option>业务主动停止</option><option>数据异常，暂停统计</option></select></label><label>最终${m.label}<input name="value" type="number" min="0" step="${m.metric==='gmv'?'0.01':'1'}" value="${value}" required /></label><label>最终门槛比例<input name="ratio" type="number" min="0" max="999" value="${ratio}" required /><span class="field-suffix">%</span></label>${m.metric==='gmv'?'<label>最终激励比例<input name="rate" type="number" min="0" step="0.01" placeholder="例如 2" /><span class="field-suffix">%</span></label>':'<label>最终达到档位<input name="tier" placeholder="例如：500单档 / ¥2.5每单" /></label>'}<label>最终激励金额<input name="bonus" type="number" min="0" step="0.01" required placeholder="请输入平台最终确认金额" /></label><label>结算备注<textarea name="note" rows="3" placeholder="补充确认人、特殊口径或外部结束情况"></textarea></label><button class="danger-button settlement-button" type="submit">确认结算并归档</button></form>`)}

