function chart(compact=false){
  const factor=state.view==='data'?activeDataFactor():1,data=(chartSets[state.range]||chartSets['7d']).map(x=>[x[0],Math.max(0,Math.round(x[1]*factor)),Math.max(0,Math.round(x[2]*factor))]);
  const isCommission=state.chartMetric==='commission',metricIndex=isCommission?2:1,maxRaw=Math.max(...data.map(x=>x[metricIndex]),1),max=Math.ceil(maxRaw/4)*4,w=720,h=compact?176:220,pL=isCommission?70:50,pR=18,pT=22,pB=32,iw=w-pL-pR,ih=h-pT-pB,step=iw/data.length,labelEvery=data.length>24?5:data.length>14?3:1;
  const format=v=>isCommission?`¥${Math.round(v).toLocaleString()}`:Math.round(v).toLocaleString();
  const grid=[0,.25,.5,.75,1].map(v=>{const value=max*(1-v);return `<line x1="${pL}" y1="${pT+ih*v}" x2="${w-pR}" y2="${pT+ih*v}" stroke="#e7ebf2"/><text x="${pL-9}" y="${pT+ih*v+4}" text-anchor="end" fill="#7f8b9e" font-size="10">${format(value)}</text>`}).join('');
  const bars=data.map((x,i)=>{const value=x[metricIndex],bh=value/max*ih,label=i%labelEvery===0||i===data.length-1,showValue=data.length<=10;return `<rect x="${pL+i*step+step*.22}" y="${pT+ih-bh}" width="${Math.max(3,step*.56)}" height="${bh}" rx="${data.length>16?2:4}" fill="${isCommission?'#f0b33d':'#416ef2'}"><title>${x[0]}：${isCommission?`预估佣金 ${money(value)}`:`有效订单 ${value} 单`}</title></rect>${showValue?`<text x="${pL+i*step+step*.5}" y="${Math.max(12,pT+ih-bh-6)}" text-anchor="middle" fill="#4a566b" font-size="9">${format(value)}</text>`:''}${label?`<text x="${pL+i*step+step*.5}" y="${h-9}" text-anchor="middle" fill="#7f8b9e" font-size="9">${x[0]}</text>`:''}`}).join('');
  return `<div class="chart-metric-switch"><button class="${!isCommission?'active':''}" data-action="chart-metric" data-metric="orders">有效订单</button><button class="${isCommission?'active':''}" data-action="chart-metric" data-metric="commission">预估佣金</button><span>单指标精确展示</span></div><div class="chart-wrap ${compact?'compact-chart':''}"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${periodText[state.range]}${isCommission?'预估佣金':'有效订单'}趋势">${grid}${bars}</svg></div><div class="chart-legend"><span><i class="legend-bar ${isCommission?'commission':''}"></i>${isCommission?'预估佣金':'有效订单'}</span><strong>${periodText[state.range]}</strong></div>`;
}

function posts(){
  let rows=postRows;if(state.range==='today')rows=rows.filter(x=>x.date==='09/23');if(state.range==='yesterday')rows=rows.filter(x=>x.date==='09/22');if(state.postGroup!=='全部')rows=rows.filter(x=>x.group===state.postGroup);if(state.postBiz!=='全部')rows=rows.filter(x=>x.biz===state.postBiz);if(state.postType!=='全部')rows=rows.filter(x=>x.type===state.postType);
  const plays=rows.reduce((n,x)=>n+x.plays,0),accounts=new Set(rows.map(x=>x.account)).size,buckets=[['低于 100',rows.filter(x=>x.plays<100).length],['100–199',rows.filter(x=>x.plays>=100&&x.plays<200).length],['200–499',rows.filter(x=>x.plays>=200&&x.plays<500).length],['500–999',rows.filter(x=>x.plays>=500&&x.plays<1000).length],['1000 以上',rows.filter(x=>x.plays>=1000).length]];
  return `${pageLead('发帖数据','每天看发帖量、参与账号、播放量和转化，并下钻到每条笔记',periodTabs(true))}<div class="notice neutral-note"><span>播放量自动采集仍待接入外部工具；当前先固定字段、统计口径和明细页。</span></div><div class="kpi-grid five">${kpi('发布笔记',rows.length,'当前筛选范围','篇')}${kpi('发帖账号',accounts,'去重后参与账号','号')}${kpi('总播放量',plays.toLocaleString(),'来自已同步笔记','播')}${kpi('业务帖',rows.filter(x=>x.type==='业务帖').length,'参与转化统计','业')}${kpi('养号帖',rows.filter(x=>x.type==='养号帖').length,'不与业务帖混算','养')}</div><div class="post-layout"><div class="card"><div class="card-head"><div><h3>播放量分布</h3><p>互斥区间，便于周报对比</p></div></div><div class="play-buckets">${buckets.map(([label,value])=>`<div><span>${label}</span><strong>${value}</strong><i><b style="width:${rows.length?value/rows.length*100:0}%"></b></i></div>`).join('')}</div></div><div class="card post-summary"><h3>过7日内容结构</h3><p><b>${rows.filter(x=>x.type==='业务帖').length}</b> 篇业务帖 · <b>${rows.filter(x=>x.type==='养号帖').length}</b> 篇养号帖</p><p>有效订单 <b>${rows.reduce((n,x)=>n+x.orders,0)}</b> 单 · 预估佣金 <b>${money(rows.reduce((n,x)=>n+x.commission,0))}</b></p></div></div><div class="card"><div class="card-head"><div><h3>笔记明细</h3><p>每个账号、每条笔记可独立追溯</p></div><div class="post-filters"><select data-action="post-group"><option>全部组别</option>${['A组','B组','C组','未分配'].map(x=>`<option ${state.postGroup===x?'selected':''}>${x}</option>`).join('')}</select><select data-action="post-biz"><option>全部业务</option>${['三福','名创优品','屈臣氏','日常内容'].map(x=>`<option ${state.postBiz===x?'selected':''}>${x}</option>`).join('')}</select><select data-action="post-type"><option>全部类型</option><option>业务帖</option><option>养号帖</option></select></div></div>${table(['日期','账号 / 组别','业务','笔记类型','笔记标题','播放量','有效订单','预估佣金'],rows.map(x=>[x.date,`<strong>${x.account}</strong><small>${x.group}</small>`,x.biz,chip(x.type,x.type==='养号帖'?'yellow':'blue'),x.title,x.plays.toLocaleString(),x.orders,money(x.commission)]),'post-table')}</div>`;
}

function accountMultiSelect(name){const groups=['A组','B组','C组','未分配'];return `<select name="${name}" multiple required size="6">${groups.map(group=>`<optgroup label="运营${group}">${accountsData.filter(x=>x[1]===group).map(x=>`<option value="${x[0]}">${x[0]} · ${x[4]}</option>`).join('')}</optgroup>`).join('')}</select><small>可按 Ctrl / Command 多选；保存后留存当时账号快照</small>`}
