function secretDetail(word){const x=secretRows.find(row=>row.word===word),meta=secretMeta[word]||{tags:[],note:''},trend=secretTrend[word]||[0,0,0,0,0,0,0],history=secretAssignments.filter(a=>a.word===word);openDrawer(`密令 · ${word}`,`<div class="drawer-section"><div class="drawer-kpis"><div><span>平台</span><b>${x.platform}</b></div><div><span>推广位命名</span><b>${x.biz}-业务帖-${x.word}</b></div><div><span>当前负责人</span><b>${x.owner}</b></div></div></div><div class="drawer-section"><h3>近7天出单趋势</h3><div class="drawer-trend">${sparkline(trend)}<strong>${trend.reduce((n,v)=>n+v,0)} 单</strong></div></div><div class="drawer-section"><h3>归属历史</h3><p>订单按“下单日期落在生效起止时间内”归属，不会因后续换人改写历史。</p>${history.length?table(['生效时间','运营组','负责人','说明'],history.map(h=>[`${h.start} — ${h.end||'至今'}`,h.group,h.owner,h.note])):'<div class="empty">待补齐历史归属</div>'}</div><div class="drawer-section"><h3>标签与备注</h3><div class="tag-list">${meta.tags.map(t=>chip(t,'blue')).join('')}</div><p>${meta.note}</p></div>`)}

function orders(){const latest=orderBatches[0],ranking=productTop10[state.orderScope];return `${pageLead('订单分析','从大量订单中看商品类型和具体商品偏好，并管理每次导入范围','<button class="primary" data-action="order-import">＋ 导入订单数据</button>')}<div class="import-status"><div><span>当前数据覆盖</span><strong>${orderBatches[orderBatches.length-1].start}—${latest.end}</strong><small>共 ${orderBatches.length} 个导入批次</small></div><div><span>最近一次导入</span><strong>${latest.name}</strong><small>${latest.imported} · ${latest.rows.toLocaleString()} 条</small></div><div class="import-warning"><span>下次建议导入</span><strong>2026-10-01 开始的数据</strong><small>自动阻止重叠日期</small></div></div><div class="view-tabs order-scope-tabs"><button class="view-tab ${state.orderScope==='latest'?'active':''}" data-action="order-scope" data-scope="latest">最新导入批次</button><button class="view-tab ${state.orderScope==='all'?'active':''}" data-action="order-scope" data-scope="all">历史累计数据</button></div><div class="card product-analysis"><div class="card-head"><div><h3>商品偏好 Top 10</h3><p>同时保留业务、类目、具体商品和业务内占比</p></div></div>${table(['排名','业务','商品类目','具体商品','订单数','业务内占比'],ranking.map((x,i)=>[`<span class="rank">${String(i+1).padStart(2,'0')}</span>`,x[0],x[1],`<strong>${x[2]}</strong>`,x[3],`${x[4]}%`]),'product-ranking')}</div><div class="card import-history"><div class="card-head"><div><h3>订单导入记录</h3><p>日期范围、条数和操作人全部留存</p></div><button class="detail-btn" data-action="order-import">登记新批次</button></div>${table(['批次名称','订单日期范围','数据条数','导入时间','操作人','状态'],orderBatches.map(x=>[x.name,`${x.start}—${x.end}`,x.rows.toLocaleString(),x.imported,x.user,chip(x.status,'green')]))}</div>`}

function reportDetail(report){const posts=Number(report.notes)||198;openDrawer(`${report.type} · ${report.period}`,`<div class="report-cover"><span>${report.type}</span><h3>${report.period} 经营复盘</h3><p>生成于 ${report.created} · ${report.status}</p></div><div class="drawer-kpis report-kpis"><div><span>发布笔记</span><b>${posts}</b></div><div><span>总播放量</span><b>86,420</b></div><div><span>有效订单</span><b>${report.orders}</b></div><div><span>预估佣金</span><b>${report.commission}</b></div></div><div class="drawer-section"><h3>播放量分布</h3>${table(['低于100','200–499','500–999','1000以上'],[['18篇','64篇','35篇','12篇']])}</div><div class="report-section-grid"><div class="drawer-section"><h3>环比变化</h3><p>笔记数 +8.2% · 播放量 +12.6% · 有效订单 +5.4%</p></div><div class="drawer-section risk-section"><h3>风险与未完成</h3>${report.risks.map(x=>`<p>• ${x}</p>`).join('')}<p>• 2 条长线任务未完成</p></div></div><div class="drawer-section"><h3>下周 3–5 个行动</h3>${report.next.map(x=>`<p>• ${x}</p>`).join('')}<p>• 复制高播放笔记的首图与标题结构</p><p>• 针对低于100播放的笔记设立对照测试</p></div>`)}

function reports(){const periods=state.reportType==='week'?['09/22—09/28','09/15—09/21','09/08—09/14']:['2026年9月','2026年8月','2026年7月'],rows=reportArchive.map(r=>[`${chip(r.type,r.type==='月报'?'blue':'green')}<strong class="report-name">${r.period} 经营复盘</strong>`,r.created,r.commission,r.orders,r.status,`<button class="detail-btn" data-action="report-detail" data-id="${r.id}">查看报告</button>`]);return `${pageLead('经营报告','周报和月报留存同一套可追溯口径','<span class="context-line">已留存 '+reportArchive.length+' 份示例档案</span>')}<div class="report-builder glass-panel"><div class="report-builder-copy"><span class="eyebrow">生成新报告</span><h3>选择周期，自动汇总经营情况</h3><p>接入飞书后，每周自动生成并写入团队共享档案。</p></div><div class="report-controls"><div class="segmented"><button class="${state.reportType==='week'?'active':''}" data-action="report-type" data-type="week">周报</button><button class="${state.reportType==='month'?'active':''}" data-action="report-type" data-type="month">月报</button></div><select class="select" data-action="report-period">${periods.map(p=>`<option ${state.reportPeriod===p?'selected':''}>${p}</option>`).join('')}</select><button class="primary" data-action="generate-report">生成并归档</button></div></div><div class="card report-preview"><div class="card-head"><div><h3>周报固定结构</h3><p>内容、转化、收益、账号、风险和行动统一口径</p></div></div><div class="report-outline expanded"><span>01 发帖量与播放分布</span><span>02 转化、佣金与激励</span><span>03 账号状态</span><span>04 上周环比趋势</span><span>05 风险与未完成</span><span>06 下周 3–5 个行动</span></div></div><div class="card"><div class="card-head"><div><h3>历史报告档案</h3><p>按生成时间留存</p></div></div>${table(['报告','生成时间','预估佣金','有效订单','归档状态','操作'],rows)}</div>`}

const channelBase=channelRows.map(r=>({orders:r.orders,gmv:r.gmv,commission:r.commission}));
let appliedRangeScale=1;
function applyRangeScale(){const next=rangeScale[state.range]||1;channelRows.forEach((r,i)=>{r.orders=Math.round(channelBase[i].orders*next);r.gmv=channelBase[i].gmv*next;r.commission=channelBase[i].commission*next});appliedRangeScale=next}

function tasksView(){
  const owners=['全部','胡心玥','高宇芸','曾涛'];let rows=tasks.map((t,i)=>({...t,index:i}));if(state.taskView==='active')rows=rows.filter(t=>!['已完成','已取消'].includes(t.status));if(state.taskView==='history')rows=rows.filter(t=>['已完成','已取消'].includes(t.status));if(state.taskView==='risk')rows=rows.filter(t=>['临期','已逾期'].includes(t.alert));if(state.taskOwner!=='全部')rows=rows.filter(t=>t.owner===state.taskOwner);
  const items=rows.map(t=>{const expanded=state.taskExpanded===String(t.index),warning=t.alert==='已逾期'?chip(t.alert,'red'):t.alert==='临期'?chip(t.alert,'yellow'):chip(t.alert==='已完成'?'已完成':'正常','blue'),history=t.history||[];return `<article class="task-item timeline-task ${expanded?'expanded':''}"><div class="task-item-main timeline-main"><div class="task-name"><strong>${t.name}</strong><span>${t.module} · ${t.owner}</span></div><div class="task-time"><span>开始</span><strong>${taskTime(t.start)}</strong></div><div class="task-time"><span>截止</span><strong>${taskTime(t.end)}</strong></div><div class="task-time"><span>完成</span><strong>${taskTime(t.actualEnd,'尚未完成')}</strong></div><div>${warning}</div><div>${taskStatusSelect(t,t.index)}</div><button class="task-expand" data-action="task-detail" data-index="${t.index}">${expanded?'收起':'查看记录'} ${expanded?'⌃':'⌄'}</button></div>${expanded?`<div class="task-detail-panel"><div><span>任务说明</span><p>${t.note}</p></div><div><span>历史进展</span>${history.length?history.map(h=>`<p><b>${h.time} · ${h.user}</b><br>${h.content}${h.progress==null?'':` · ${h.progress}%`}</p>`).join(''):`<p>${t.report}</p>`}</div><div class="task-report-action"><span>进展入口</span><button class="primary" data-action="task-progress" data-index="${t.index}">填写进展</button></div></div>`:''}</article>`}).join('');
  return `${pageLead('任务中心','状态与时间由系统管理，执行人通过“填写进展”持续汇报','<button class="primary" data-action="add">＋ 新建任务</button>')}<div class="kpi-grid task-kpis">${kpi('进行中',tasks.filter(t=>t.status==='进行中').length,'已开始执行','进')}${kpi('未开始',tasks.filter(t=>t.status==='未开始').length,'等待确认','未')}${kpi('临期 / 逾期',tasks.filter(t=>['临期','已逾期'].includes(t.alert)).length,'需要关注','期',null,'risk')}${kpi('历史归档',tasks.filter(t=>['已完成','已取消'].includes(t.status)).length,'完成后不删除','史')}</div><div class="card task-list-card"><div class="card-head task-head"><div><h3>任务明细</h3><p>展开任务后可填写进展并查看历史</p></div><div class="task-controls"><div class="view-tabs">${[['active','进行中'],['all','全部'],['risk','临期 / 逾期'],['history','历史归档']].map(x=>`<button class="view-tab ${state.taskView===x[0]?'active':''}" data-action="task-view" data-filter="${x[0]}">${x[1]}</button>`).join('')}</div><select class="select" data-action="task-owner">${owners.map(o=>`<option ${state.taskOwner===o?'selected':''}>${o==='全部'?'全部负责人':o}</option>`).join('')}</select></div></div><div class="task-list">${items||'<div class="empty">当前无任务</div>'}</div></div>`;
}

function employeesView(){const filtered=employees.filter(e=>state.employeeStatus==='全部'||e.status===state.employeeStatus);return `${pageLead('员工中心','仅管理员可查看人员全量业绩、在离职状态和历史归属','<button class="primary" data-action="permission-detail">权限说明</button>')}<div class="permission-banner"><div><strong>管理员专区</strong><span>当前为原型预览。正式版由飞书授权身份 + 中台角色表在服务端校验，不只是隐藏菜单。</span></div>${chip('仅管理员可见','red')}</div><div class="employee-statusbar"><div class="view-tabs">${['在职','离职','全部'].map(x=>`<button class="view-tab ${state.employeeStatus===x?'active':''}" data-action="employee-status" data-status="${x}">${x}</button>`).join('')}</div><button class="detail-btn" data-action="employee-entry">＋ 员工档案</button></div><div class="employee-list">${filtered.map(e=>`<article class="employee-card ${e.status==='离职'?'former':''}"><div class="employee-summary enhanced" data-action="employee" data-name="${e.name}"><div class="employee-main"><div class="employee-avatar">${e.name.slice(-1)}</div><div><strong>${e.name}</strong><span>${e.group} · ${e.status}</span></div></div><div class="employee-stat"><span>负责账号</span><b>${e.accounts}</b></div><div class="employee-stat"><span>累计笔记</span><b>${e.notes}</b></div><button class="employee-stat metric-link" data-action="employee-data" data-name="${e.name}" data-group="${e.group}" data-range="30d"><span>近30天佣金 ↗</span><b>¥${e.d30.toLocaleString()}</b></button><div class="employee-stat"><span>当前任务</span><b>${e.tasks}</b></div><span>${state.employee===e.name?'⌃':'⌄'}</span></div>${state.employee===e.name?employeeDetail(e):''}</article>`).join('')}</div>`}

function permissionDrawer(){openDrawer('角色与数据权限',`<div class="drawer-section"><h3>权限不直接等于飞书表格权限</h3><p>飞书 OAuth 负责确认“谁在登录”；中台角色表负责确认“他能看什么、能改什么”。</p></div>${table(['角色','可见范围','可修改范围'],[['管理员','全部页面，含员工中心和操作日志','全部业务数据'],['组长','本组账号、笔记、任务和经营数据','本组业务数据'],['员工','自己的账号、任务和笔记','自己负责的记录']])}<div class="notice compact-notice"><span>GitHub Pages 是静态网站，无法安全强制这套权限；正式接入时需增加后端服务并在每个读写接口校验。</span></div>`)}
function postsV5(){return posts().replace('过7日内容结构','近7日内容结构')}

const renderers={overview,data:dataView,posts:postsV5,reports,accounts,business,tasks:tasksView,experiments,employees:employeesView,orders,secrets,tools,logs};
function render(preserveScroll=false){
  const y=window.scrollY;
  document.querySelector('#title').textContent=labels[state.view];
  document.querySelector('#crumb').textContent=labels[state.view];
  document.querySelector('#app').innerHTML=renderers[state.view]();
  document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.view===state.view));
  const taskBadge=document.querySelector('[data-view="tasks"] b');
  if(taskBadge)taskBadge.textContent=tasks.filter(t=>t.status!=='已完成'&&t.status!=='已取消').length;
  if(state.view==='tasks'){
    const values=document.querySelectorAll('.task-kpis .kpi-value');
    const counts=[tasks.filter(t=>t.status==='进行中').length,tasks.filter(t=>t.status==='未开始').length,tasks.filter(t=>['临期','已逾期'].includes(t.alert)).length,tasks.filter(t=>['已完成','已取消'].includes(t.status)).length];
    values.forEach((el,i)=>el.textContent=counts[i]);
  }
  window.scrollTo({top:preserveScroll?y:0,behavior:'auto'});
}
function goto(view){if(renderers[view]){state.view=view;render()}}
function toast(msg){const el=document.querySelector('#toast');el.textContent=msg;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2200)}
function openDrawer(title,body){const layer=document.querySelector('#drawer');layer.innerHTML=`<aside class="drawer"><div class="drawer-head"><h2>${title}</h2><button class="drawer-close" data-action="close">×</button></div>${body}</aside>`;layer.classList.add('open');layer.setAttribute('aria-hidden','false')}
function closeDrawer(){const layer=document.querySelector('#drawer');layer.classList.remove('open');layer.setAttribute('aria-hidden','true')}
function accountDetail(i){const a=accountsData[i];openDrawer(a[0],`<div class="drawer-section"><div class="drawer-kpis"><div><span>账号状态</span><b>${a[3]}</b></div><div><span>生命周期</span><b>${a[2]}</b></div><div><span>负责人</span><b>${a[4]}</b></div></div></div><div class="drawer-section"><h3>基础信息</h3>${table(['字段','内容'],[['组别',a[1]],['账号性质','专业号'],['新增 / 启用日期',a[5]],['所属企业','待飞书同步'],['IP 网络','待飞书同步']])}</div>`)}
function placementDetail(name){const r=channelRows.find(x=>x.pos===name);openDrawer(name,`<div class="drawer-section"><div class="drawer-kpis"><div><span>有效订单</span><b>${r.orders}</b></div><div><span>成交金额</span><b>${money(r.gmv)}</b></div><div><span>预估佣金</span><b>${money(r.commission)}</b></div></div></div><div class="drawer-section"><h3>归属关系</h3>${table(['层级','内容'],[['组 / 渠道',r.g],['平台',r.p],['业务',r.biz],['推广位',r.pos]])}</div><div class="drawer-section"><h3>查看逻辑</h3><p>正式接入后，这里继续展示该推广位的每日趋势、订单明细和负责人。</p></div>`)}
function activityDetail(id){const a=incentiveActivities.find(x=>x.id===id),m=activityModels[id]||activityModels['act-01'],value=m.metric==='gmv'?m.current:a.orders;openDrawer(a.name,`<div class="drawer-section"><div class="drawer-kpis"><div><span>活动时间</span><b>${a.start}—${a.end}</b></div><div><span>${m.label}</span><b>${formatMetric(m,value)}</b></div><div><span>激励规则</span><b>${m.reward}</b></div></div></div><div class="drawer-section"><h3>活动要求</h3><p>${a.requirement}</p></div><div class="drawer-section"><h3>${a.phase==='ended'?'结算结果':'关联数据'}</h3>${table(['指标','数据'],[['统计口径',m.label],['启用账号',`${a.accounts} 个`],['发布笔记',`${a.notes} 篇`],['当前业绩',formatMetric(m,value)],['激励金额',a.bonus]])}</div>${a.phase==='active'?`<button class="danger-button secondary-danger" data-action="settle-activity" data-id="${a.id}">进入活动结算</button>`:''}`)}

document.addEventListener('change',e=>{if(e.target.dataset.action==='task-owner'){state.taskOwner=e.target.value==='全部负责人'?'全部':e.target.value;render(true)}if(e.target.dataset.action==='task-status'){const t=tasks[Number(e.target.dataset.index)];t.status=e.target.value;if(t.status==='已完成'){t.alert='已完成';t.progress=100}else if(t.alert==='已完成'){t.alert='正常'}render(true);toast('工作状态已更新；正式版会同步写回飞书')}if(e.target.dataset.action==='data-owner'){state.dataOwner=e.target.value==='全部负责人'?'全部':e.target.value;if(state.dataOwner!=='全部')state.dataGroup=employees.find(x=>x.name===state.dataOwner).group;state.dataSource='';render(true)}if(e.target.dataset.action==='data-platform'){state.dataPlatform=e.target.value==='全部平台'?'全部':e.target.value;render(true)}if(e.target.dataset.action==='data-biz'){state.dataBiz=e.target.value==='全部业务'?'全部':e.target.value;render(true)}if(e.target.dataset.action==='data-search'){state.dataSearch=e.target.value;render(true)}if(e.target.dataset.action==='secret-search'){state.secretSearch=e.target.value;render(true)}});
document.addEventListener('change',e=>{if(e.target.dataset.action==='report-period'){state.reportPeriod=e.target.value}if(e.target.dataset.action==='task-status'){const t=tasks[Number(e.target.dataset.index)];if(e.target.value==='已完成'&&!t.actualEnd)t.actualEnd=new Date().toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'});if(e.target.value!=='已完成')t.actualEnd='';addOperation('更新任务状态',t.name,`状态调整为 ${e.target.value}${t.actualEnd?`；实际完成 ${t.actualEnd}`:''}`);render(true)}});
document.addEventListener('change',e=>{if(e.target.dataset.action==='post-group'){state.postGroup=e.target.value==='全部组别'?'全部':e.target.value;render(true)}if(e.target.dataset.action==='post-biz'){state.postBiz=e.target.value==='全部业务'?'全部':e.target.value;render(true)}if(e.target.dataset.action==='post-type'){state.postType=e.target.value==='全部类型'?'全部':e.target.value;render(true)}});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&['data-search','secret-search'].includes(e.target.dataset.action)){if(e.target.dataset.action==='data-search')state.dataSearch=e.target.value;else state.secretSearch=e.target.value;render(true)}});
document.addEventListener('click',e=>{const el=e.target.closest('[data-action],[data-view].nav-item');if(!el)return;const a=el.dataset.action;if(el.classList.contains('nav-item'))return goto(el.dataset.view);if(a==='goto')return goto(el.dataset.view);if(a==='range'){state.range=el.dataset.range;return render(state.view==='data')}if(a==='data-group'){state.dataGroup=el.dataset.group;state.dataOwner='全部';state.dataSource='';return render(true)}if(a==='toggle-data-trend'){state.dataTrendCollapsed=!state.dataTrendCollapsed;return render(true)}if(a==='employee-data'){state.dataGroup=el.dataset.group;state.dataOwner=el.dataset.name;state.range=el.dataset.range||'30d';state.dataPlatform='全部';state.dataBiz='全部';state.dataSearch='';state.dataSource='employee';return goto('data')}if(a==='employee-accounts'){state.accountGroup=el.dataset.group;return goto('accounts')}if(a==='clear-employee-filter'){state.dataOwner='全部';state.dataGroup='全部';state.dataSource='';return render(true)}if(a==='account-group'){state.accountGroup=el.dataset.group;return render(true)}if(a==='task-filter'){state.taskFilter=el.dataset.filter;return render(true)}if(a==='task-detail'){state.taskExpanded=state.taskExpanded===el.dataset.index?'':el.dataset.index;return render(true)}if(a==='activity-view'){state.activityView=el.dataset.filter;return render(true)}if(a==='secret-group'){state.secretGroup=el.dataset.group;return render(true)}if(a==='secret-platform'){state.secretPlatform=el.dataset.platform;return render(true)}if(a==='employee'){state.employee=state.employee===el.dataset.name?'':el.dataset.name;return render(true)}if(a==='account-detail')return accountDetail(Number(el.dataset.index));if(a==='placement-detail')return placementDetail(el.dataset.pos);if(a==='activity-detail')return activityDetail(el.dataset.id);if(a==='close')return closeDrawer();if(a==='refresh')return toast('当前为结构预览；连接飞书后将刷新真实数据');if(a==='add')return toast('接入飞书后将在对应底表中新建记录');if(a==='import')return toast('订单模块暂不作为当前主线');if(a==='tool-open')return toast('接入工具链接后将直接打开');if(a==='edit-tool')return toast('工具信息会存入“工具与自动化”底表');if(a==='login')return toast('需要先配置飞书自建应用的 OAuth 授权信息');if(a==='repair')return toast('已模拟启动健康检查；正式版会调用对应流程的恢复动作')});
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;if(a==='report-type'){state.reportType=el.dataset.type;state.reportPeriod=state.reportType==='week'?'09/22—09/28':'2026年9月';return render(true)}if(a==='generate-report')return generateReport();if(a==='report-detail')return reportDetail(reportArchive.find(x=>x.id===el.dataset.id));if(a==='custom-date')return customDateDrawer();if(a==='task-view'){state.taskView=el.dataset.filter;return render(true)}if(a==='experiment-status'){state.experimentStatus=el.dataset.status;return render(true)}if(a==='experiment-detail')return experimentDetail(el.dataset.id);if(a==='experiment-task'){state.taskView='active';state.taskOwner=el.dataset.owner;return goto('tasks')}if(a==='new-experiment')return newExperimentDrawer();if(a==='stop-activity')return stopActivityDrawer(el.dataset.id);if(a==='settle-activity')return settlementDrawer(el.dataset.id);if(a==='employee-status'){state.employeeStatus=el.dataset.status;return render(true)}if(a==='employee-entry')return employeeEntryDrawer();if(a==='order-scope'){state.orderScope=el.dataset.scope;return render(true)}if(a==='order-import')return orderImportDrawer();if(a==='secret-detail')return secretDetail(el.dataset.word);if(a==='log-tab'){state.logTab=el.dataset.tab;return render(true)}});
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action;if(a==='chart-metric'){state.chartMetric=el.dataset.metric;render(true)}if(a==='task-progress')taskProgressDrawer(Number(el.dataset.index));if(a==='permission-detail')permissionDrawer();if(a==='range'||a==='employee-data'){applyRangeScale();render(true)}});
document.addEventListener('submit',e=>{
  if(e.target.id==='stop-activity-form'){
    e.preventDefault();const form=new FormData(e.target),activity=incentiveActivities.find(x=>x.id===e.target.dataset.id),previous=activity.orders;
    Object.assign(activity,{orders:Number(form.get('orders')),phase:'ended',status:'人工停止',end:'09/23',requirement:`${activity.requirement} 停止原因：${safe(form.get('reason'))}；门槛比例 ${safe(form.get('ratio'))}%。`});
    activityOverrides[activity.id]={orders:activity.orders,phase:activity.phase,status:activity.status,end:activity.end,requirement:activity.requirement};storage.write('ops-activity-overrides-v1',activityOverrides);addOperation('停止激励活动',activity.name,`${previous} 单 → ${activity.orders} 单；${form.get('reason')}`);closeDrawer();state.activityView='ended';render();toast('活动已停止并转入历史结果');
  }
  if(e.target.id==='new-experiment-form'){
    e.preventDefault();const form=new FormData(e.target),aAccounts=form.getAll('aAccounts').map(safe),bAccounts=form.getAll('bAccounts').map(safe),row={id:`exp-${Date.now()}`,name:safe(form.get('name')),type:safe(form.get('type')),target:safe(form.get('target')),hypothesis:safe(form.get('hypothesis')),metric:safe(form.get('metric')),owner:safe(form.get('owner')),start:safe(form.get('start')),end:safe(form.get('end')),activity:'待关联',secret:`${safe(form.get('aSecret'))} / ${safe(form.get('bSecret'))}`,status:'进行中',task:form.get('createTask')?'已创建执行任务':'未创建任务',baseline:'待录入基准',goal:safe(form.get('goal')),result:'等待采集数据',conclusion:'实验进行中',groupA:{name:'实验A组',accounts:aAccounts.join('、'),accountSnapshot:aAccounts,secret:safe(form.get('aSecret')),strategy:safe(form.get('aStrategy'))},groupB:{name:'实验B组',accounts:bAccounts.join('、'),accountSnapshot:bAccounts,secret:safe(form.get('bSecret')),strategy:safe(form.get('bStrategy'))}};
    experimentRows.unshift(row);if(form.get('createTask'))tasks.push({name:`执行实验：${row.name}`,module:'业务测试',owner:row.owner,start:row.start,end:row.end,status:'未开始',alert:'正常',progress:null,note:`${row.target}；A组：${row.groupA.accounts}；B组：${row.groupB.accounts}`,report:'尚未提交进展。',actualEnd:''});addOperation('新建业务实验',row.name,`负责人：${row.owner}；A/B密令：${row.secret}`);closeDrawer();render();toast('实验已保存，执行任务已同步创建');
  }
  if(e.target.id==='custom-date-form'){
    e.preventDefault();const form=new FormData(e.target),start=String(form.get('start')),end=String(form.get('end'));if(start>end)return toast('开始日期不能晚于结束日期');state.customStart=start;state.customEnd=end;const begin=new Date(`${start}T00:00:00`),finish=new Date(`${end}T00:00:00`),days=Math.min(62,Math.max(1,Math.round((finish-begin)/86400000)+1));chartSets.custom=Array.from({length:days},(_,i)=>{const d=new Date(begin);d.setDate(d.getDate()+i);const orders=38+[8,15,6,22,12,19,10][i%7]+i%4*2;return [`${String(d.getMonth()+1).padStart(2,'0')}/${String(d.getDate()).padStart(2,'0')}`,orders,orders*27+(i%3)*96]});const totalOrders=chartSets.custom.reduce((n,x)=>n+x[1],0),totalCommission=chartSets.custom.reduce((n,x)=>n+x[2],0);summary.custom=[money(totalCommission),totalOrders.toLocaleString(),money(totalOrders*76.8),'3.78%'];periodText.custom=`自定义 · ${start.slice(5).replace('-','/')}—${end.slice(5).replace('-','/')}`;rangeScale.custom=days/7;state.range='custom';applyRangeScale();closeDrawer();render();toast('已应用自定义日期范围');
  }
  if(e.target.id==='task-progress-form'){
    e.preventDefault();const form=new FormData(e.target),task=tasks[Number(e.target.dataset.index)],value=form.get('progress')===''?null:Number(form.get('progress')),entry={time:new Date().toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}),user:'当前预览用户',content:safe(form.get('content')),progress:value};task.history=task.history||[];task.history.unshift(entry);task.report=`${entry.time}：${entry.content}`;task.progress=value;task.status=safe(form.get('status'));if(task.status==='已完成'){task.alert='已完成';task.actualEnd=entry.time}addOperation('提交任务进展',task.name,entry.content);closeDrawer();render(true);toast('进展已保存并追加到历史记录');
  }
  if(e.target.id==='settlement-form'){
    e.preventDefault();const form=new FormData(e.target),activity=incentiveActivities.find(x=>x.id===e.target.dataset.id),model=activityModels[activity.id],reason=String(form.get('reason')),value=Number(form.get('value')),bonus=Number(form.get('bonus'));model.current=value;if(model.metric==='orders')activity.orders=value;Object.assign(activity,{phase:'ended',status:reason==='活动按计划正常结束'?'正常结束':'提前停止',end:'10/04',bonus:money(bonus),requirement:`${activity.requirement} 结算方式：${safe(reason)}；最终门槛比例 ${safe(form.get('ratio'))}%。`});activityOverrides[activity.id]={orders:activity.orders,phase:activity.phase,status:activity.status,end:activity.end,bonus:activity.bonus,requirement:activity.requirement};storage.write('ops-activity-overrides-v1',activityOverrides);addOperation('完成活动结算',activity.name,`${reason}；最终${model.label} ${formatMetric(model,value)}；激励 ${money(bonus)}`);closeDrawer();state.activityView='ended';render();toast('活动结算已归档');
  }
  if(e.target.id==='employee-form'){
    e.preventDefault();const form=new FormData(e.target),name=safe(form.get('name'));if(employees.some(x=>x.name===name))return toast('该员工已存在，请修改原档案');employees.push({name,group:safe(form.get('group')),accounts:0,d7:0,d30:0,notes:0,tasks:0,list:'尚未分配账号',task:'无',progress:0,status:safe(form.get('status')),joined:safe(form.get('joined')),left:''});addOperation('新增员工档案',name,`组别：${form.get('group')}；状态：${form.get('status')}`);closeDrawer();state.employeeStatus=String(form.get('status'));render();toast('员工档案已新增');
  }
  if(e.target.id==='order-import-form'){
    e.preventDefault();const form=new FormData(e.target),start=String(form.get('start')),end=String(form.get('end'));if(start>end)return toast('订单开始日期不能晚于结束日期');const overlap=orderBatches.find(x=>start<=x.end&&end>=x.start);if(overlap)return toast(`日期与“${overlap.name}”重叠，请调整范围`);const file=e.target.querySelector('input[type="file"]'),batch={id:`batch-${Date.now()}`,name:safe(form.get('name')),start,end,rows:0,imported:new Date().toLocaleString('zh-CN',{year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}),user:'当前预览用户',status:file&&file.files.length?'等待解析':'已登记范围'};orderBatches.unshift(batch);storage.write('ops-order-batches-v1',orderBatches);addOperation('登记订单批次',batch.name,`${start}—${end}；${batch.status}`);closeDrawer();render();toast('导入日期范围已登记');
  }
});
document.querySelector('#login').addEventListener('click',()=>toast('需要先配置飞书自建应用的 OAuth 授权信息'));
document.querySelector('#drawer').addEventListener('click',e=>{if(e.target.id==='drawer')closeDrawer()});
render();
